```yaml
name: PR Issue Link Check

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

jobs:
  check-issue-link:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Validate issue references
        uses: actions/github-script@v6
        with:
          script: |
            const issueRegex = /(Fixes|Closes|Resolves)\s+#(\\d+)/gi;
            const pr = context.payload.pull_request;
            const body = pr.body || '';
            const title = pr.title || '';

            // Get commit messages
            const commits = await github.rest.pulls.listCommits({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pr.number,
            });

            let commitMessages = '';
            for (const commit of commits.data) {
              commitMessages += commit.commit.message + '\\n';
            }

            // Combine all text to search for issue references
            const combinedText = body + '\\n' + title + '\\n' + commitMessages;
            const matches = [...combinedText.matchAll(issueRegex)];

            if (matches.length === 0) {
              core.setFailed(
                'No issue references found in PR title, body, or commit messages. ' +
                'Please reference an issue using "Fixes #123", "Closes #456", or "Resolves #789".'
              );
            }

            // Validate each referenced issue exists
            const issueNumbers = [...new Set(matches.map(m => m[2]))];
            for (const num of issueNumbers) {
              try {
                await github.rest.issues.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(num, 10),
                });
              } catch (error) {
                core.setFailed(`Referenced issue #${num} does not exist in this repository.`);
              }
            }
